		country: raw.country,
		date: raw.date,
		onsetTimeStr: raw.onsetTimeStr,
		disasterType: raw.disasterType,
		isControlEvent: raw.isControlEvent,
		casualties: raw.casualties,
		peakPrecipitation: raw.peakPrecipitation,
